package com.descent3.droid;

import android.content.Context;
import android.content.pm.PackageManager;
import android.content.res.AssetManager;
import android.util.Log;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.Comparator;
import java.util.stream.Stream;

/**
 * Extracts the game data generated by the native build (d3-android.hog, online/*.d3c), which is
 * packaged under assets/gamedata/, onto the filesystem so the game can fopen() it.
 */
public final class BuiltinGameData {
  private static final String TAG = "BuiltinGameData";
  private static final String ASSET_ROOT = "gamedata";
  private static final String STAMP_FILE = ".apk-stamp";

  private BuiltinGameData() {}

  /**
   * Ensures {@code dest} holds the game data from this APK, re-extracting it whenever the APK has
   * been installed or updated since the last extraction. This copies well over 100MB, so it must
   * not be called on the UI thread.
   */
  public static void extract(Context ctx, Path dest) throws IOException {
    String stamp = apkStamp(ctx);
    Path stampFile = dest.resolve(STAMP_FILE);
    if (Files.isRegularFile(stampFile)
        && stamp.equals(new String(Files.readAllBytes(stampFile), StandardCharsets.UTF_8))) {
      return;
    }

    Log.i(TAG, "Extracting built-in game data to " + dest);
    deleteRecursively(dest);
    Files.createDirectories(dest);
    copyAssetTree(ctx.getAssets(), ASSET_ROOT, dest);
    // Written last, so an interrupted extraction is redone on the next launch.
    Files.write(stampFile, stamp.getBytes(StandardCharsets.UTF_8));
  }

  private static String apkStamp(Context ctx) {
    try {
      return Long.toString(ctx.getPackageManager()
        .getPackageInfo(ctx.getPackageName(), 0).lastUpdateTime);
    } catch (PackageManager.NameNotFoundException e) {
      throw new IllegalStateException("Own package not found", e);
    }
  }

  private static void copyAssetTree(AssetManager assets, String assetPath, Path dest)
      throws IOException {
    String[] children = assets.list(assetPath);
    if (children == null || children.length == 0) {
      // A file (the APK doesn't contain empty directories).
      try (InputStream in = assets.open(assetPath, AssetManager.ACCESS_STREAMING)) {
        Files.copy(in, dest, StandardCopyOption.REPLACE_EXISTING);
      }
      return;
    }
    Files.createDirectories(dest);
    for (String child : children) {
      copyAssetTree(assets, assetPath + "/" + child, dest.resolve(child));
    }
  }

  private static void deleteRecursively(Path path) throws IOException {
    if (!Files.exists(path)) {
      return;
    }
    try (Stream<Path> paths = Files.walk(path)) {
      for (Path p : (Iterable<Path>) paths.sorted(Comparator.reverseOrder())::iterator) {
        Files.delete(p);
      }
    }
  }
}
